create or replace function public.consume_api_rate(p_subject text,p_bucket_start timestamptz,p_limit bigint) returns boolean language plpgsql set search_path=public,pg_catalog as $function$ declare current_count bigint; begin insert into public.api_rate_buckets(subject,bucket_start,requests) values(p_subject,p_bucket_start,1) on conflict(subject,bucket_start) do update set requests=public.api_rate_buckets.requests+1 returning requests into current_count; if current_count>p_limit then update public.api_rate_buckets set requests=requests-1 where subject=p_subject and bucket_start=p_bucket_start; return false; end if; return true; end $function$;
create or replace function public.create_customer_organization(p_type text,p_legal_name text,p_country_code text default null,p_domain text default null,p_registration_number text default null) returns uuid language plpgsql set search_path=public,pg_catalog as $function$ declare v_id uuid; begin if auth.uid() is null then raise exception 'authentication required'; end if; if p_type not in ('company','government','security_provider','developer','client','partner','individual') then raise exception 'invalid organization type'; end if; insert into public.customer_organizations(owner_user_id,organization_type,legal_name,country_code,website_domain,registration_number) values(auth.uid(),p_type,trim(p_legal_name),nullif(upper(trim(p_country_code)),''),nullif(lower(trim(p_domain)),''),nullif(trim(p_registration_number),'')) returning id into v_id; insert into public.organization_members(organization_id,user_id,role,status) values(v_id,auth.uid(),'owner','active'); return v_id; end $function$;
create or replace function public.request_workspace_admission(p_organization_id uuid) returns uuid language plpgsql set search_path=public,pg_catalog as $function$ declare v_id uuid; begin if auth.uid() is null then raise exception 'authentication required'; end if; if not exists(select 1 from public.customer_organizations where id=p_organization_id and owner_user_id=auth.uid()) then raise exception 'organization_not_found'; end if; if exists(select 1 from public.organization_admissions where organization_id=p_organization_id and status in ('pending','review')) then raise exception 'admission_already_pending'; end if; insert into public.organization_admissions(organization_id,requested_by) values(p_organization_id,auth.uid()) returning id into v_id; update public.customer_organizations set admission_status='pending',updated_at=now() where id=p_organization_id; return v_id; end $function$;
create or replace function public.revoke_organization_invitation(p_invitation_id uuid) returns void language plpgsql set search_path=public,pg_catalog as $function$ begin if auth.uid() is null then raise exception 'authentication required'; end if; if not exists(select 1 from public.organization_invitations i join public.organization_members m on m.organization_id=i.organization_id where i.id=p_invitation_id and m.user_id=auth.uid() and m.status='active' and m.role in ('owner','admin')) then raise exception 'invitation_not_found'; end if; update public.organization_invitations set expires_at=least(expires_at,now()),accepted_at=coalesce(accepted_at,now()) where id=p_invitation_id and accepted_at is null; end $function$;